 * @name chb_Grp_Mf_onclick
 * @description chb_Grp_Mf 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chb_Grp_Mf_onclick = function() {
    try {
        chb_Grp_All.setValue(0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24702.chb_Grp_Mf_onclick" });
    }
};

/**
 * @method
 * @name chb_Grp_If_onclick
 * @description chb_Grp_If 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chb_Grp_If_onclick = function() {
    try {
        chb_Grp_All.setValue(0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24702.chb_Grp_If_onclick" });
    }
