///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let secuGrpId = "";
    if (chb_Grp_St.getValue() === 'Y') secuGrpId += 'ST,';
    if (chb_Grp_Mf.getValue() === 'Y') secuGrpId += 'MF,';
    if (chb_Grp_Rt.getValue() === 'Y') secuGrpId += 'RT,';
    if (chb_Grp_Sc.getValue() === 'Y') secuGrpId += 'SC,';
    if (chb_Grp_Fs.getValue() === 'Y') secuGrpId += 'FS,';
    if (chb_Grp_Dr.getValue() === 'Y') secuGrpId += 'DR,';
    if (chb_Grp_If.getValue() === 'Y') secuGrpId += 'IF,';
    if (chb_Grp_All.getValue() === ' Y') secuGrpId = '';
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    if (dts_List.getRowCount() > 0) {
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF24702.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, {fileName: "리스트", type: "3"});
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

/**
 * @method
 * @name allCheck
 * @description all Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.allCheck = function() {
    const checkArray = [chb_Grp_St, chb_Grp_Mf, chb_Grp_Sc, chb_Grp_Rt, chb_Grp_Dr, chb_Grp_Fs, chb_Grp_If];
    if (chb_Grp_All.checked === true) {
        for (let i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
